import { NextRequest, NextResponse } from "next/server";
import axios from "axios";

interface SpotifyAccessTokenResponse {
  access_token: string;
  token_type: string;
  expires_in: number;
}

interface SpotifyTrack {
  id: string;
  name: string;
  artists: Array<{ name: string }>;
  album: {
    images: Array<{ url: string; height?: number; width?: number }>;
  };
}

interface SpotifySearchResponse {
  tracks: {
    items: SpotifyTrack[];
  };
}

async function getSpotifyAccessToken(): Promise<string> {
  const clientId = process.env.SPOTIFY_CLIENT_ID;
  const clientSecret = process.env.SPOTIFY_CLIENT_SECRET;

  if (!clientId || !clientSecret) {
    throw new Error("Missing Spotify credentials in environment variables");
  }

  const authString = Buffer.from(`${clientId}:${clientSecret}`).toString(
    "base64"
  );

  try {
    const response = await axios.post<SpotifyAccessTokenResponse>(
      "https://accounts.spotify.com/api/token",
      "grant_type=client_credentials",
      {
        headers: {
          Authorization: `Basic ${authString}`,
          "Content-Type": "application/x-www-form-urlencoded",
        },
      }
    );

    return response.data.access_token;
  } catch (error) {
    console.error("Error fetching Spotify access token:", error);
    throw new Error("Failed to authenticate with Spotify API");
  }
}

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const query = searchParams.get("q");

    if (!query) {
      return NextResponse.json(
        { error: "Missing search query parameter 'q'" },
        { status: 400 }
      );
    }

    // Get access token
    const accessToken = await getSpotifyAccessToken();

    // Search for track
    const searchResponse = await axios.get<SpotifySearchResponse>(
      "https://api.spotify.com/v1/search",
      {
        params: {
          q: query,
          type: "track",
          limit: 1,
        },
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      }
    );

    const tracks = searchResponse.data.tracks.items;

    if (tracks.length === 0) {
      return NextResponse.json(
        { error: "No tracks found for the given query" },
        { status: 404 }
      );
    }

    const track = tracks[0];
    const coverUrl =
      track.album.images.length > 0 ? track.album.images[0].url : null;

    return NextResponse.json(
      {
        id: track.id,
        title: track.name,
        artist: track.artists[0]?.name || "Unknown Artist",
        coverUrl,
      },
      { status: 200 }
    );
  } catch (error) {
    console.error("Spotify API error:", error);

    if (error instanceof Error) {
      return NextResponse.json(
        { error: error.message },
        { status: 500 }
      );
    }

    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
